lag() {   # the primary's replication offset minus the replica's acknowledged one
  /bin/redis-cli -h primary INFO replication 2>/dev/null | tr -d '\r' | awk -F'[:=,]' '
    $1 == "master_repl_offset" { m = $2 } $1 == "slave0" { for (i = 2; i < NF; i += 2) if ($i == "offset") o = $(i + 1) }
    END { if (o == "") print "none"; else print m - o }'
}
